/* ---------- 書類一覧（点検日ごとのフォルダ。本日のフォルダだけ開いておく） ---------- */
function foldByDate(l,rowFn){const g={},td=today();l.forEach(x=>{const k=x.date||'';(g[k]=g[k]||[]).push(x)});
  const keys=Object.keys(g).sort((a,b)=>a===td?-1:b===td?1:b.localeCompare(a));
  return (g[td]?'':'<div class="card"><p class="muted">本日（'+td.replace(/-/g,'/')+'）の書類はまだありません。</p></div>')+
    keys.map(k=>'<details class="fold"'+(k===td?' open':'')+'><summary><span class="fic">📁</span>'+(k===td?'本日 ':'')+esc(k?k.replace(/-/g,'/'):'日付なし')+'<span class="muted">　'+g[k].length+'件</span></summary><div class="list">'+g[k].map(rowFn).join('')+'</div></details>').join('')}

